#!/bin/bash
set -euo pipefail

mkdir -p /logs/verifier

# Run the mixer to generate output (only if not already generated by solve.sh)
if [ ! -f /app/runtime/mix_output.json ] || [ ! -f /app/runtime/mix_stats.json ]; then
    python3 /app/runtime/mixer.py /app/runtime/mix_session.json
fi

# Run pytest validation using uv
set +e
uv run --with pytest pytest /tests/test_mixer.py -v --tb=short
TEST_EXIT=$?
set -e

if [ "$TEST_EXIT" -eq 0 ]; then
    echo 1 > /logs/verifier/reward.txt
else
    echo 0 > /logs/verifier/reward.txt
fi

cat /logs/verifier/reward.txt
exit "$TEST_EXIT"
